package net.civeira.phylax.features.document.theme.application.policy;

import jakarta.enterprise.event.Observes;
import net.civeira.phylax.common.security.Actor;
import net.civeira.phylax.features.document.theme.application.visibility.ThemeVisibilityCheck;

public class TenantAccesible {

  /**
   * Constant for platform field
   *
   * @autogenerated VisibilityPolicyGenerator
   */
  private static final String ROL_PLATFORM = "platform:*";

  /**
   * @autogenerated VisibilityPolicyGenerator
   * @param filter
   */
  public void filterVisibles(@Observes ThemeVisibilityCheck filter) {
    Actor actor = filter.getActor();
    if (!actor.hasRole(ROL_PLATFORM)) {
      filter.peek(fl -> fl.setTenantTenantAccesible(actor.getTenant().orElse(null)));
    }
  }
}
